import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color } from 'three/webgpu';
import { uv, mix, color, vec3 } from 'three/tsl';
import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'nav-dock';
  const pos = config?.scenePlacement?.position || [0, 0, 0];
  group.position.set(pos[0], pos[1], pos[2]);

  const railW = 3.6, railH = 0.5;

  // Rail material — brushed metal gradient
  const railMat = new MeshStandardNodeMaterial();
  const topColor = color(new Color('#1b1b23'));
  const botColor = color(new Color('#101015'));
  railMat.colorNode = mix(botColor, topColor, uv().y);
  railMat.roughness = 0.55;
  railMat.metalness = 0.5;
  railMat.clearcoat = 0.2;
  railMat.clearcoatRoughness = 0.3;

  const railGeo = new THREE.PlaneGeometry(railW, railH, 1, 1);
  const rail = new THREE.Mesh(railGeo, railMat);
  rail.position.z = 0.15;
  group.add(rail);

  // Contact shadow plane
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.colorNode = color(new Color('#000000'));
  shadowMat.transparent = true;
  shadowMat.opacity = 0.35;
  const shadowGeo = new THREE.PlaneGeometry(railW * 0.98, railH * 0.98, 1, 1);
  const shadowPlane = new THREE.Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0, -0.06, 0.0);
  group.add(shadowPlane);

  // Entries
  const labels = ['HOME', 'FEATURES', 'COLLECTION', 'PRICING', 'JOURNAL'];
  const centers = [];
  const startX = -0.68 * 2;
  for (let i = 0; i < 5; i++) centers.push(startX + i * 0.68);

  const inactiveColor = '#a6adba';
  const activeColor = '#e8ecf2';
  const accentColor = '#ff2a38';

  const cells = [];
  let activeIndex = 0;

  const textMeshes = [];

  for (let i = 0; i < labels.length; i++) {
    const isActive = i === activeIndex;
    const cell = new THREE.Group();
    cell.position.set(centers[i], 0, 0.16);
    cell.userData.index = i;

    const style = isActive ? { fontSize: 13, fontWeight: 700 } : { fontSize: 13, fontWeight: 400 };
    const textNode = ctx.fontAtlas.createText({
      text: labels[i],
      family: 'JetBrains Mono',
      fontSize: style.fontSize,
      fontWeight: style.fontWeight,
      letterSpacing: 0.08,
      color: isActive ? activeColor : inactiveColor,
      align: 'center',
    });
    textNode.position.set(0, 0, 0.01);
    cell.add(textNode);
    textMeshes.push(textNode);

    // hit cell (invisible interactive plane)
    const hitMat = new MeshBasicNodeMaterial();
    hitMat.colorNode = color(new Color('#000000'));
    hitMat.transparent = true;
    hitMat.opacity = 0.0;
    const hitGeo = new THREE.PlaneGeometry(0.6, 0.34);
    const hit = new THREE.Mesh(hitGeo, hitMat);
    hit.name = 'hit-' + labels[i];
    cell.add(hit);

    group.add(cell);
    cells.push({ cell, hit, textNode, label: labels[i] });
  }

  // Underline bar
  const barMat = new MeshBasicNodeMaterial();
  barMat.colorNode = color(new Color(accentColor));
  const barGeo = new THREE.PlaneGeometry(0.28, 0.025);
  const bar = new THREE.Mesh(barGeo, barMat);
  bar.position.set(centers[activeIndex], -0.06, 0.17);
  group.add(bar);

  // Mount rise-in animation
  group.position.y += 0.4;
  const mountTl = gsap.timeline();
  mountTl.to(group.position, {
    y: pos[1],
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  });

  const activeTl = gsap.timeline();

  function setActive(index) {
    if (index === activeIndex) return;
    const prev = activeIndex;
    activeIndex = index;

    cells.forEach((c, i) => {
      const target = i === index ? activeColor : inactiveColor;
      if (c.textNode.setColor) c.textNode.setColor(target);
    });

    activeTl.clear();
    activeTl.to(bar.position, {
      x: centers[index],
      duration: 0.26,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      onComplete: () => {
        gsap.fromTo(bar.scale, { x: 1 }, { x: 1.04, duration: 0.08, yoyo: true, repeat: 1, ease: 'power2.out' });
      },
    });
  }

  const pressTweens = new Map();

  function pressDown(index) {
    const c = cells[index];
    if (!c) return;
    const tween = gsap.to(c.cell.scale, {
      x: 0.97, y: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    });
    gsap.to(c.cell.position, { z: 0.13, duration: 0.12, ease: 'back.out(1.7)' });
    pressTweens.set(index, tween);
  }

  function pressUp(index) {
    const c = cells[index];
    if (!c) return;
    gsap.to(c.cell.scale, { x: 1, y: 1, duration: 0.12, ease: 'back.out(1.7)' });
    gsap.to(c.cell.position, { z: 0.16, duration: 0.12, ease: 'back.out(1.7)' });
  }

  function hoverIn(index) {
    const c = cells[index];
    if (!c || index === activeIndex) return;
    if (c.textNode.setColor) c.textNode.setColor(activeColor);
  }

  function hoverOut(index) {
    const c = cells[index];
    if (!c || index === activeIndex) return;
    if (c.textNode.setColor) c.textNode.setColor(inactiveColor);
  }

  group.userData.handlers = {
    onPointerDown: (event) => {
      const idx = event?.userData?.index ?? event?.index;
      if (idx != null) pressDown(idx);
    },
    onPointerUp: (event) => {
      const idx = event?.userData?.index ?? event?.index;
      if (idx != null) {
        pressUp(idx);
        setActive(idx);
      }
    },
    onPointerOver: (event) => {
      const idx = event?.userData?.index ?? event?.index;
      if (idx != null) hoverIn(idx);
    },
    onPointerOut: (event) => {
      const idx = event?.userData?.index ?? event?.index;
      if (idx != null) hoverOut(idx);
    },
  };

  cells.forEach((c, i) => { c.cell.userData.index = i; c.hit.userData.index = i; });

  group.userData.cleanup = () => {
    mountTl.kill();
    activeTl.kill();
    pressTweens.forEach((t) => t.kill());
    railGeo.dispose();
    railMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    barGeo.dispose();
    barMat.dispose();
    cells.forEach((c) => {
      c.hit.geometry.dispose();
      c.hit.material.dispose();
      if (c.textNode.dispose) c.textNode.dispose();
    });
  };

  return group;
}
